/**
 * Indicator catalog — extracted from the official Logística division catalog
 * (23 indicators, 50 fields, 239 rules) and narrowed to the eleven weekly ones
 * that apply to a warehouse operation.
 *
 * This is DATA, not code: the capture form is generated by reading this file.
 * Adding an indicator means adding an entry here, never writing JSX.
 *
 * Field ids, labels, help text and rule messages are kept verbatim from the
 * source catalog. The messages are written for the person doing the capture;
 * they are not reworded, not translated and not "improved".
 */

/** `BASE` is the formula's denominator; `NUMERATOR` goes on top. */
export type FieldRole = "BASE" | "NUMERATOR";

/** `COUNT` is whole units; `DECIMAL` allows fractions. */
export type FieldType = "COUNT" | "DECIMAL";

/** Which way is good for this indicator to move. Drives colour. */
export type Direction = "HIGHER_IS_BETTER" | "LOWER_IS_BETTER";

export interface Field {
  id: string;
  label: string;
  role: FieldRole;
  type: FieldType;
  unit: string | null;
  required: boolean;
  min: number | null;
  max: number | null;
  decimals: number;
  help: string | null;
}

/**
 * Field-scoped rules only — the ones that can be evaluated without a server.
 * They all reject: they blame the person capturing and are fixed on the spot.
 *
 * Submission-scoped rules (window, duplicate, variance, sender) escalate rather
 * than reject — they ask for a human decision and hold the submission — and
 * need an audit log plus an accepted previous period. Out of scope here.
 */
export interface Rule {
  id: string;
  fieldId: string;
  kind: "TYPE" | "RANGE" | "CONSISTENCY" | "NONZERO_BASE";
  expression: string;
  message: string;
}

export interface Indicator {
  id: string;
  name: string;
  domain: string;
  /** The formula in prose, as it comes from the catalog. Unsigned. */
  formula: string;
  direction: Direction;
  fields: Field[];
  rules: Rule[];
}

