/** Every field of the eleven indicators, in capture order. */
export const FIELDS: Field[] = INDICATORS.flatMap((i) => i.fields);

export const INDICATOR_COUNT = INDICATORS.length;
export const FIELD_COUNT = FIELDS.length;

export function getIndicator(id: string): Indicator | undefined {
  return INDICATORS.find((i) => i.id === id);
}
